// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();
        uint256 aliceBalanceBefore = alice.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(alice);
        c.withdrawBalance();
        uint256 aliceBalanceAfter = alice.balance;
        uint256 contractBalanceAfter = address(c).balance;
        assertTrue(contractBalanceAfter == 0);
    }
}
